// Safe direct lookup function returning PROGMEM pointer without indirect pointer arrays
inline const uint16_t* getSpriteAiFrame(int animIdx, int frameIdx) {
  (void)animIdx;
  if (frameIdx < 0 || frameIdx >= SPRITE_AI_FRAME_COUNT) frameIdx = 0;
  switch (frameIdx) {
    case 0: return luna_sprite_ai_anim0_frame_00;
    case 1: return luna_sprite_ai_anim0_frame_01;
    case 2: return luna_sprite_ai_anim0_frame_02;
    case 3: return luna_sprite_ai_anim0_frame_03;
    case 4: return luna_sprite_ai_anim0_frame_04;
    case 5: return luna_sprite_ai_anim0_frame_05;
    case 6: return luna_sprite_ai_anim0_frame_06;
    case 7: return luna_sprite_ai_anim0_frame_07;
    default: return luna_sprite_ai_anim0_frame_00;
  }
}

